import math
import numpy as np
M = np.array([[0.16, 0.03, 0.05, 0.03], [0.03, 0.16, 0.03, 0.05],
              [0.05, 0.03, 0.16, 0.03], [0.03, 0.05, 0.03, 0.16]])
EX = np.array([0.12, 0.38, 0.38, 0.12])
EY = np.array([0.16, 0.34, 0.34, 0.16])
def _lae(*v):
    top = max(v)
    return top if top == -math.inf else top + math.log(sum(math.exp(t - top) for t in v))
def _tables(x, y, em, ex, ey, go, ge):
    n, m, ninf = len(x), len(y), -math.inf
    lo, le = math.log(go), math.log(ge)
    F = np.full((3, n + 1, m + 1), ninf)
    F[0, 0, 0] = 0.0
    for i in range(n + 1):
        for j in range(m + 1):
            if i and j:
                F[0, i, j] = math.log(em[x[i-1], y[j-1]]) + _lae(*F[:, i-1, j-1])
            if i:
                F[1, i, j] = math.log(ex[x[i-1]]) + _lae(lo + F[0, i-1, j], le + F[1, i-1, j])
            if j:
                F[2, i, j] = math.log(ey[y[j-1]]) + _lae(lo + F[0, i, j-1], le + F[2, i, j-1])
    B = np.full((3, n + 1, m + 1), ninf)
    B[:, n, m] = 0.0
    for i in range(n, -1, -1):
        for j in range(m, -1, -1):
            if i == n and j == m:
                continue
            mm = math.log(em[x[i], y[j]]) + B[0, i+1, j+1] if i < n and j < m else ninf
            gx = math.log(ex[x[i]]) + B[1, i+1, j] if i < n else ninf
            gy = math.log(ey[y[j]]) + B[2, i, j+1] if j < m else ninf
            B[0, i, j] = _lae(mm, lo + gx, lo + gy)
            B[1, i, j] = _lae(mm, le + gx)
            B[2, i, j] = _lae(mm, le + gy)
    return F, B
def _pin(counts):
    c = np.asarray(counts, dtype=float)
    if c.shape != (2,):
        return -1.0
    return float(1.0 + 1.0e3 * c[0] + 1.0e2 * c[1])
x = np.array([0, 2, 1, 3, 3, 0, 1]); y = np.array([0, 2, 2, 3, 0, 1])
em, ex, ey, go, ge = M, EX, EY, 0.04, 0.4
F, B = _tables(x, y, em, ex, ey, go, ge)
assert np.allclose(_pin(compute_expected_gap_transition_counts(x.copy(), y.copy(), em.copy(), ex.copy(), ey.copy(), go, ge, F.copy(), B.copy())), target)

