M = ((0.16, 0.03, 0.05, 0.03), (0.03, 0.16, 0.03, 0.05), (0.05, 0.03, 0.16, 0.03), (0.03, 0.05, 0.03, 0.16))
EX = (0.12, 0.38, 0.38, 0.12)
EY = (0.16, 0.34, 0.34, 0.16)
def _pair(seed, length, dp, sp):
    rng = np.random.default_rng(seed)
    x = rng.integers(0, 4, length); u = rng.random(length); v = rng.integers(0, 4, length)
    return x, np.where(u < dp + sp, v, x)[u >= dp]
def _lae(*v):
    top = max(v)
    return top if top == -math.inf else top + math.log(sum(math.exp(t - top) for t in v))
def _log_z(x, y, em, ex, ey, go, ge):
    em, ex, ey = np.asarray(em), np.asarray(ex), np.asarray(ey)
    n, m = len(x), len(y)
    lo, le = math.log(go), math.log(ge)
    F = np.full((3, n + 1, m + 1), -math.inf)
    F[0, 0, 0] = 0.0
    for i in range(n + 1):
        for j in range(m + 1):
            if i and j:
                F[0, i, j] = math.log(em[x[i-1], y[j-1]]) + _lae(*F[:, i-1, j-1])
            if i:
                F[1, i, j] = math.log(ex[x[i-1]]) + _lae(lo + F[0, i-1, j], le + F[1, i-1, j])
            if j:
                F[2, i, j] = math.log(ey[y[j-1]]) + _lae(lo + F[0, i, j-1], le + F[2, i, j-1])
    return _lae(*F[:, n, m])
def _targets(seed, length, dp, sp, em, ex, ey, go, ge, h=1.0e-4):
    x, y = _pair(seed, length, dp, sp)
    up = _log_z(x, y, em, ex, ey, go * math.exp(h), ge) - _log_z(x, y, em, ex, ey, go * math.exp(-h), ge)
    ue = _log_z(x, y, em, ex, ey, go, ge * math.exp(h)) - _log_z(x, y, em, ex, ey, go, ge * math.exp(-h))
    return round(up / (2 * h), 5), round(ue / (2 * h), 5)
n_open, n_extend = _targets(2, 3, 0.0, 0.0, M, EX, EY, 0.3, 0.5)
assert np.allclose(estimate_mean_neighbour_epistasis(2, 3, 0.0, 0.0, M, EX, EY, n_open, n_extend), target)

